-- Ensure previously seeded stock rooms also carry the base tag. Updating the
-- seed JSON alone does not repair normalized tags already stored in D1.
INSERT OR IGNORE INTO room_tag (room_id, tag, type, is_primary_genre)
SELECT room_id, 'base', 0, 0 FROM room
WHERE json_extract(data, '$.Name') IN (
  'RecCenter', 'TheInkSpace', 'PerformanceHall', 'MakerRoom', 'Park', 'River',
  'Homestead', 'Quarry', 'Clearcut', 'Spillway', 'Lake', 'PropulsionTestRange',
  'Gym', 'Stadium', 'Hangar', 'CyberJunkCity', 'BowlingAlley',
  'StuntRunnerBaseRoom', 'DriveIn', 'ChillCozyClubhouse', 'CatwalkTemplate',
  'ModernStoreTemplate', 'YoutubeTemplate', 'PVPTemplate', 'CozyStoreTemplate',
  'GraduationTemplate', 'RaceTrackTemplate', 'OutdoorMeeting', 'SkiLodgeTemplate',
  'CustomDorm_RoomTemplate', 'CostumesTemplate', 'WeddingTemplate', 'BeachTerrain',
  'MakerPenClass_Template'
);
